@override
Widget build(BuildContext context) {
  final palette = Theme.of(context).extension<AppPalette>()!;
  final typography = Theme.of(context).extension<AppTypography>()!;
  // read (not watch): the dot animates off [spectrumListenable] below, so this
  // widget must NOT rebuild on every controller notify.
  final player = context.read<PlaybackController>();

  return LayoutBuilder(
    builder: (context, constraints) {
      final reservedForTitle = config.showSongInfo
          ? _estimatedTitleBlockHeight(
              typography: typography,
              textScale: config.textScale,
            ) + 12
          : 0.0;

      final dotAreaHeight = max(0.0, constraints.maxHeight - reservedForTitle);
      final maxAllowed =
          min(constraints.maxWidth, dotAreaHeight) / 2;

      return BaseHeroContainer(
        child: Stack(
          children: [
            // Optional song-info overlay pinned to the top of the hero band
            // (B-020), above the dot.
            if (config.showSongInfo)
              Positioned(
                left: 0,
                right: 0,
                top: 12,
                child: Opacity(
                  opacity: config.textOpacity.clamp(0.0, 1.0),
                  child: HeroTitleBlock(textScale: config.textScale),
                ),
              ),

            // Pulsing dot — centered in the remaining (non-title) area, so the
            // overlay never intersects/clips the dot even at max text size.
            Positioned.fill(
              child: Align(
                alignment: Alignment.topCenter,
                child: SizedBox(
                  height: dotAreaHeight,
                  child: Center(
                    child: RepaintBoundary(
                      child: AnimatedBuilder(
                        animation: player.spectrumListenable,
                        builder: (context, _) {
                          final r = _radiusFor(player.spectrumData, maxAllowed);
                          return Container(
                            width: r * 2,
                            height: r * 2,
                            decoration: BoxDecoration(
                              color: palette.fgPrimary
                                  .withValues(alpha: config.dotOpacity),
                              shape: BoxShape.circle,
                            ),
                          );
                        },
                      ),
                    ),
                  ),
                ),
              ),
            ),
          ],
        ),
      );
    },
  );
}

double _estimatedTitleBlockHeight({
  required AppTypography typography,
  required double textScale,
}) {
  // Match HeroTitleBlock's layout: Artist (H1, up to 2 lines), then an 8px
  // spacer (when artist exists) and the Song (H2, up to 2 lines). We
  // pessimistically assume the artist path so we always reserve enough.
  final h1 = typography.heroSize * textScale;
  final h2 = typography.heroSize * heroSongSizeFactor * textScale;

  const lineHeightFactor = 1.18; // heroHeadingStyle.height
  final twoLineH1 = lineHeightFactor * h1 * 2;
  final twoLineH2 = lineHeightFactor * h2 * 2;

  return twoLineH1 + 8 + twoLineH2;
}
